package com.example.editor.textual.runtime;

import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import com.example.editor.concurrent.BoundedPermitPool;
import com.example.editor.grammar.application.GrammarCompilationService;
import com.example.editor.grammar.runtime.GrammarCompilationSnapshot;
import com.example.editor.textual.TextualModelProperties;
import com.example.editor.textual.definition.*;
import com.example.editor.textual.persistence.*;
import com.example.editor.textual.source.TextualModelSourceDocument;
import com.example.editor.validation.model.CanonicalModelDocument;
import com.example.editor.validation.persistence.StoredCanonicalDocument;

@Service
public class TextualModelSessionService {
    private final TextualModelSessionRepository repository;private final TextualEditorDefinitionService definitions;private final TextualModelProperties properties;
    private final GrammarCompilationService compilations;private final TextualSharedLayerRuntimeService sharedLayers;private final NeutralTextualModelParser parser=new NeutralTextualModelParser();private final BoundedPermitPool parseSlots;
    /** Descripción: Inicializa una instancia de TextualModelSessionService con sus dependencias y datos de entrada. Entradas: r: dato de entrada necesario para la operación; d: dato de entrada necesario para la operación; p: dato de entrada necesario para la operación; c: dato de entrada necesario para la operación; s: dato de entrada necesario para la operación. Salida: deja la instancia inicializada y lista para su uso. */ public TextualModelSessionService(TextualModelSessionRepository r,TextualEditorDefinitionService d,TextualModelProperties p,GrammarCompilationService c,TextualSharedLayerRuntimeService s){repository=r;definitions=d;properties=p;compilations=c;sharedLayers=s;parseSlots=new BoundedPermitPool(p.getMaximumConcurrentParses());}
    /** Descripción: Crea o prepara el resultado de «create» dentro de TextualSemanticLookupResult. Entradas: req: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>create(CreateTextualModelSessionRequest req){
        requireEnabled();if(req==null||req.editorDefinitionId().isBlank())throw new IllegalArgumentException("Textual editor definition is required");
        TextualEditorDefinitionModel def=definitions.find(req.editorDefinitionId()).document();GrammarCompilationSnapshot snapshot=definitions.resolveSnapshot(def);String id=req.sessionId().isBlank()?"textual-"+UUID.randomUUID():req.sessionId();validateDocuments(req.documents());
        TextualParseResult parsed=parseProtected(0,req.documents(),snapshot);TextualModelSession session=new TextualModelSession(id,def.id(),def.grammarId(),snapshot.id(),req.documents(),0,0,parsed.sourceHash(),parsed.valid()?parsed.semanticModel():null,parsed.valid()?parsed.sourceMap():List.of(),null,0,boundedDiagnostics(parsed.diagnostics()),Instant.now(),Map.of("lastKnownGood",parsed.valid()?"revision:0":"none","draftValid",Boolean.toString(parsed.valid()),"grammarSnapshotPinned","true"));return repository.create(session);
    }
    /** Descripción: Obtiene la información correspondiente a «find» dentro de TextualSemanticLookupResult. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>find(String id){requireEnabled();return repository.find(id).orElseThrow(()->new NoSuchElementException("Textual model session not found: "+id));}
    /** Descripción: Ejecuta la operación «parse» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: id: identificador que delimita el recurso objetivo; req: dato de entrada necesario para la operación; etag: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>parse(String id,ParseTextualModelRequest req,String etag){
        StoredCanonicalDocument<TextualModelSession>stored=find(id);TextualModelSession previous=stored.document();if(req==null)throw new IllegalArgumentException("Parse request is required");
        if(req.draftRevision()<previous.draftRevision())throw new IllegalArgumentException("Stale textual draft revision");
        if(req.draftRevision()==previous.draftRevision()){
            if(previous.documents().equals(req.documents()))return stored;
            throw new IllegalArgumentException("Conflicting textual draft revision: the same revision cannot contain different documents");
        }
        validateDocuments(req.documents());GrammarCompilationSnapshot snapshot=compilations.find(previous.grammarSnapshotId());if(!snapshot.successful())throw new IllegalStateException("The session grammar snapshot is no longer usable");
        TextualParseResult parsed=parseProtected(req.draftRevision(),req.documents(),snapshot);CanonicalModelDocument semantic=parsed.valid()?parsed.semanticModel():previous.lastValidSemanticModel();var sourceMap=parsed.valid()?boundedSourceMap(parsed.sourceMap()):previous.lastValidSourceMap();Map<String,String>meta=new LinkedHashMap<>(previous.metadata());meta.put("lastKnownGood",parsed.valid()?"revision:"+req.draftRevision():meta.getOrDefault("lastKnownGood","none"));meta.put("draftValid",Boolean.toString(parsed.valid()));meta.put("parseAt",Instant.now().toString());
        TextualModelSession next=new TextualModelSession(previous.id(),previous.editorDefinitionId(),previous.grammarId(),snapshot.id(),req.documents(),req.draftRevision(),req.draftRevision(),parsed.sourceHash(),semantic,sourceMap,previous.lastCommittedSemanticModel(),previous.lastCommittedRevision(),boundedDiagnostics(parsed.diagnostics()),Instant.now(),meta);return repository.replace(id,next,etag==null?stored.etag():etag);
    }
    /** Descripción: Actualiza el estado gestionado por TextualSemanticLookupResult mediante la operación «save». Entradas: id: identificador que delimita el recurso objetivo; etag: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession>save(String id,String etag){
        StoredCanonicalDocument<TextualModelSession>stored=find(id);TextualModelSession s=stored.document();if(!s.draftValid()||s.lastParsedRevision()!=s.draftRevision()||s.lastValidSemanticModel()==null)throw new IllegalStateException("Only the current valid textual draft can be promoted");
        TextualEditorDefinitionModel definition=definitions.find(s.editorDefinitionId()).document();
        TextualSharedLayerExecutionReport validation=sharedLayers.validateBeforeCommit(definition,s,s.lastValidSemanticModel());
        if(validation.validationExecuted()&&!validation.validationSuccessful())throw new IllegalStateException("Shared HYDRA validation rejected the textual semantic commit: "+String.join("; ",validation.warnings()));
        Map<String,String>meta=new LinkedHashMap<>(s.metadata());meta.put("savedAt",Instant.now().toString());meta.put("savedRevision",Long.toString(s.draftRevision()));meta.put("sharedValidationExecuted",Boolean.toString(validation.validationExecuted()));meta.put("sharedValidationDiagnostics",Integer.toString(validation.validationDiagnostics()));if(!validation.warnings().isEmpty())meta.put("sharedLayerWarnings",String.join(" | ",validation.warnings()));
        TextualModelSession next=new TextualModelSession(s.id(),s.editorDefinitionId(),s.grammarId(),s.grammarSnapshotId(),s.documents(),s.draftRevision(),s.lastParsedRevision(),s.lastParsedSourceHash(),s.lastValidSemanticModel(),s.lastValidSourceMap(),s.lastValidSemanticModel(),s.draftRevision(),s.diagnostics(),Instant.now(),meta);
        StoredCanonicalDocument<TextualModelSession> committed=repository.replace(id,next,etag==null?stored.etag():etag);
        sharedLayers.afterPersistedCommit(definition,committed.document(),s.lastCommittedSemanticModel(),committed.document().lastCommittedSemanticModel());
        return committed;
    }
    /** Devuelve el último modelo semántico válido de una sesión para proyecciones y generación. Los borradores rotos nunca sustituyen esta vista. */
    /** Descripción: Ejecuta la operación «modelForPerspectives» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public CanonicalModelDocument modelForPerspectives(String id){
        TextualModelSession session=find(id).document();
        if(session.lastValidSemanticModel()==null)throw new IllegalStateException("No valid semantic model is available for textual session: "+id);
        return session.lastValidSemanticModel();
    }

    /** Descripción: Ejecuta la operación «semanticAt» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: id: identificador que delimita el recurso objetivo; documentId: identificador que delimita el recurso objetivo; line: dato de entrada necesario para la operación; column: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public TextualSemanticLookupResult semanticAt(String id,String documentId,int line,int column){TextualModelSession s=find(id).document();var map=new com.example.editor.textual.source.TextualSemanticSourceMap(s.lastValidSourceMap());return map.at(documentId,new com.example.editor.grammar.core.TextPosition(line,column)).map(e->new TextualSemanticLookupResult(true,e,s.lastValidSemanticModel()==null?null:s.lastValidSemanticModel().findElement(e.semanticId()).orElse(null))).orElse(new TextualSemanticLookupResult(false,null,null));}
    /** Descripción: Ejecuta la operación «commitReconciled» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: id: identificador que delimita el recurso objetivo; expectedEtag: dato de entrada necesario para la operación; reconciliation: dato de entrada necesario para la operación; evidence: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ public StoredCanonicalDocument<TextualModelSession> commitReconciled(String id,String expectedEtag,TextualReconciliationResult reconciliation,Map<String,String> evidence){
        StoredCanonicalDocument<TextualModelSession> stored=find(id);TextualModelSession previous=stored.document();
        if(reconciliation==null||!reconciliation.safe()||reconciliation.parsed()==null||!reconciliation.parsed().valid()||reconciliation.parsed().semanticModel()==null)throw new IllegalArgumentException("Only a safe, reparsed textual reconciliation can be committed");
        long nextRevision=previous.draftRevision()+1;if(reconciliation.parsed().revision()!=nextRevision)throw new IllegalArgumentException("Reconciliation revision does not match the current textual draft");
        Map<String,String> meta=new LinkedHashMap<>(previous.metadata());if(evidence!=null)meta.putAll(evidence);meta.put("lastKnownGood","revision:"+nextRevision);meta.put("draftValid","true");meta.put("reconciledAt",Instant.now().toString());meta.put("reconciliationEdits",Integer.toString(reconciliation.edits().size()));
        TextualParseResult parsed=reconciliation.parsed();TextualModelSession next=new TextualModelSession(previous.id(),previous.editorDefinitionId(),previous.grammarId(),previous.grammarSnapshotId(),reconciliation.documents(),nextRevision,nextRevision,parsed.sourceHash(),parsed.semanticModel(),boundedSourceMap(parsed.sourceMap()),previous.lastCommittedSemanticModel(),previous.lastCommittedRevision(),boundedDiagnostics(parsed.diagnostics()),Instant.now(),meta);
        return repository.replace(id,next,expectedEtag==null||expectedEtag.isBlank()?stored.etag():expectedEtag);
    }
    /** Descripción: Ejecuta la operación «parseProtected» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: revision: dato de entrada necesario para la operación; docs: dato de entrada necesario para la operación; snapshot: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private TextualParseResult parseProtected(long revision,List<TextualModelSourceDocument>docs,GrammarCompilationSnapshot snapshot){BoundedPermitPool.Permit permit=null;try{permit=parseSlots.tryAcquire(Duration.ofMillis(properties.getPermitAcquireTimeoutMillis()));if(permit==null)throw new IllegalStateException("Textual parse capacity is busy; retry later");return parser.parse(revision,docs,snapshot,properties.getMaximumDiagnostics());}catch(InterruptedException e){Thread.currentThread().interrupt();throw new java.util.concurrent.CancellationException("Textual parsing interrupted");}finally{if(permit!=null)permit.close();}}
    /** Descripción: Ejecuta la operación «boundedDiagnostics» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: values: colección de elementos que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private List<TextualModelDiagnostic> boundedDiagnostics(List<TextualModelDiagnostic> values){return values.size()<=properties.getMaximumDiagnostics()?List.copyOf(values):List.copyOf(values.subList(0,properties.getMaximumDiagnostics()));}
    /** Descripción: Ejecuta la operación «boundedSourceMap» correspondiente a la responsabilidad de TextualSemanticLookupResult. Entradas: values: colección de elementos que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private List<com.example.editor.textual.source.TextualSemanticSourceMapEntry> boundedSourceMap(List<com.example.editor.textual.source.TextualSemanticSourceMapEntry> values){if(values.size()>properties.getMaximumSourceMapEntries())throw new IllegalArgumentException("Textual semantic source map exceeds configured entry limit");return List.copyOf(values);}
    /** Descripción: Valida las condiciones necesarias para «validateDocuments» y rechaza entradas no válidas. Entradas: docs: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void validateDocuments(List<TextualModelSourceDocument>docs){if(docs==null||docs.isEmpty())throw new IllegalArgumentException("At least one textual model document is required");if(docs.size()>properties.getMaximumDocuments())throw new IllegalArgumentException("Too many textual model documents");Set<String>ids=new HashSet<>(),paths=new HashSet<>();long total=0;for(TextualModelSourceDocument d:docs){if(!ids.add(d.id())||!paths.add(d.relativePath().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("Textual model document ids and paths must be unique");long bytes=d.content().getBytes(StandardCharsets.UTF_8).length;total+=bytes;if(bytes>properties.getMaximumDocumentBytes())throw new IllegalArgumentException("Textual model document exceeds configured size limit: "+d.relativePath());}if(total>properties.getMaximumTotalBytes())throw new IllegalArgumentException("Textual model exceeds configured total size limit");}
    /** Descripción: Valida las condiciones necesarias para «requireEnabled» y rechaza entradas no válidas. Entradas: no requiere parámetros de entrada. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void requireEnabled(){if(!properties.isEnabled())throw new IllegalStateException("Textual model module is disabled");}
    public record TextualSemanticLookupResult(boolean found,com.example.editor.textual.source.TextualSemanticSourceMapEntry sourceMap,com.example.editor.validation.model.CanonicalModelElement element){}
}
